import{_ as t,o as a,c as r,ak as o}from"./chunks/framework.B8jO0odJ.js";const u=JSON.parse('{"title":"Chainy learner and teacher guide","description":"Draft for the adopted October 12 design. Miguel and Sean must verify button names and screenshots against the actual beta build before distribution.","frontmatter":{"title":"Chainy learner and teacher guide","description":"Draft for the adopted October 12 design. Miguel and Sean must verify button names and screenshots against the actual beta build before distribution.","source":"docs/user-guide.md","category":"Guides & tooling","sourceUpdated":"2026-10-12T21:55:56+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/user-guide.md","filePath":"content/docs/user-guide.md"}'),s={name:"content/docs/user-guide.md"};function i(n,e,d,l,c,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<div><h1 id="chainy-learner-and-teacher-guide">Chainy learner and teacher guide<a class="header-anchor" href="#chainy-learner-and-teacher-guide" aria-label="Link to this section">​</a></h1><p>Draft for the adopted October 12 design. Miguel and Sean must verify button names and screenshots against the actual beta build before distribution.</p><h2 id="learner-steps">Learner steps<a class="header-anchor" href="#learner-steps" aria-label="Link to this section">​</a></h2><ol><li>Open Chainy and enter/select the local learner profile provided for the session.</li><li>Follow the movement and interaction instructions in the learning level.</li><li>Read the lesson or dialogue, then start the available Quiz, Wordle or BlockMatch activity.</li><li>Follow the activity instructions and read the feedback.</li><li>Wait for the save result before leaving. If saving fails, follow the retry message.</li><li>Return to the level, replay as allowed, or leave.</li><li>Ask the teacher to help switch profiles before handing a shared device to another learner.</li></ol><p>Your code selects a profile on this device. It does not recover progress from another phone.</p><h2 id="teacher-steps">Teacher steps<a class="header-anchor" href="#teacher-steps" aria-label="Link to this section">​</a></h2><p>Use the approved build and participant procedure. Confirm the correct learner profile before play. Follow the agreed assessment and assistance rules.</p><p>After play, use the tested collection method to export approved records and confirm that staff can read them. Keep local data until the responsible custodian confirms the next step. Do not put learner records in GitHub.</p><p>Installing the app, collecting results and installing an update are separate operations. Gameplay remains offline.</p><h2 id="if-something-goes-wrong">If something goes wrong<a class="header-anchor" href="#if-something-goes-wrong" aria-label="Link to this section">​</a></h2><table><thead><tr><th>Situation</th><th>Action</th></tr></thead><tbody><tr><td>Wrong learner is shown</td><td>Stop and select the correct profile before playing</td></tr><tr><td>Code is rejected or creates an unexpected new profile</td><td>Check with the teacher; do not use someone else&#39;s code</td></tr><tr><td>Save fails</td><td>Follow the retry prompt; do not assume progress was saved</td></tr><tr><td>App closes</td><td>Reopen and use the last supported saved point</td></tr><tr><td>Collection fails</td><td>Keep local records and retry with staff support</td></tr><tr><td>Update is required</td><td>Use the approved tested update; do not uninstall as a routine update step</td></tr></tbody></table><p>Report device/build, affected activity, steps and the visible error. Sherwin coordinates help; Christian handles technical problems; Miguel reproduces screen issues; Sean handles study-record questions.</p></div>',1)])])}const f=t(s,[["render",i]]);export{u as __pageData,f as default};
